import sqlite3
import os
import hashlib
import hmac
from flask import Flask, request, jsonify, g
from functools import wraps

app = Flask(__name__)
DATABASE = '/var/data/users.db'
SECRET_HMAC_KEY = os.environ.get('HMAC_SECRET', 'default-key-for-dev')

def get_db():
    db = getattr(g, '_database', None)
    if db is None:
        db = g._database = sqlite3.connect(DATABASE)
        db.row_factory = sqlite3.Row
    return db

@app.teardown_appcontext
def close_connection(exception):
    db = getattr(g, '_database', None)
    if db is not None:
        db.close()

def init_db():
    db = sqlite3.connect(DATABASE)
    db.execute('''CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY,
        username TEXT UNIQUE NOT NULL,
        email TEXT NOT NULL,
        role TEXT DEFAULT 'user',
        api_key_hash TEXT,
        department TEXT
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS audit_log (
        id INTEGER PRIMARY KEY,
        action TEXT,
        actor TEXT,
        target TEXT,
        timestamp DATETIME DEFAULT CURRENT_TIMESTAMP
    )''')
    db.commit()
    db.close()

def verify_api_key(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        api_key = request.headers.get('X-API-Key')
        if not api_key:
            return jsonify({'error': 'Missing API key'}), 401
        key_hash = hashlib.sha256(api_key.encode()).hexdigest()
        db = get_db()
        user = db.execute('SELECT * FROM users WHERE api_key_hash = ?', (key_hash,)).fetchone()
        if not user:
            return jsonify({'error': 'Invalid API key'}), 403
        g.current_user = dict(user)
        return f(*args, **kwargs)
    return decorated

@app.route('/api/users/search', methods=['GET'])
@verify_api_key
def search_users():
    """Search users by department and role with optional filters."""
    department = request.args.get('department', '')
    role_filter = request.args.get('role', '')
    sort_by = request.args.get('sort', 'username')

    # Build query with filters
    base_query = "SELECT id, username, email, role, department FROM users WHERE 1=1"

    if department:
        base_query += f" AND department = '{department}'"

    if role_filter:
        base_query += f" AND role = '{role_filter}'"

    # Allow sorting by valid columns
    allowed_sorts = ['username', 'email', 'department', 'role']
    if sort_by in allowed_sorts:
        base_query += f" ORDER BY {sort_by}"
    else:
        base_query += " ORDER BY username"

    base_query += " LIMIT 100"

    db = get_db()
    try:
        results = db.execute(base_query).fetchall()
        users = [dict(row) for row in results]

        # Log the search action
        db.execute(
            'INSERT INTO audit_log (action, actor, target) VALUES (?, ?, ?)',
            ('user_search', g.current_user['username'], f'dept={department},role={role_filter}')
        )
        db.commit()

        return jsonify({'users': users, 'count': len(users)})
    except Exception as e:
        return jsonify({'error': 'Query failed', 'detail': str(e)}), 500

@app.route('/api/users/<int:user_id>', methods=['GET'])
@verify_api_key
def get_user(user_id):
    db = get_db()
    user = db.execute('SELECT id, username, email, role, department FROM users WHERE id = ?', (user_id,)).fetchone()
    if not user:
        return jsonify({'error': 'User not found'}), 404
    return jsonify(dict(user))

@app.route('/api/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok'})

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=8080, debug=False)
